{
  "exit_code": 0,
  "timed_out": false,
  "stdout": "     1	/**
     2	 * Качество руды (содержание меди) и извлечение на обогатительной фабрике.
     3	 *
     4	 * Содержание Cu в забое меняется по ходу отработки блока (рудное тело неоднородно):
     5	 * базовое значение + медленная волна с периодом в несколько часов. Фабрика работает лучше всего,
     6	 * когда питание ровное и близко к целевому: отклонение снижает извлечение меди в концентрат.
     7	 */
     8	import type { SimConfig } from './config';
     9	import type { Excavator } from './types';
    10	
    11	/** Содержание меди в забое экскаватора в момент времени, %. */
    12	export function gradeAt(ex: Excavator, now: number): number {
    13	  if (ex.gradeBase <= 0) return 0;
    14	  const g = ex.gradeBase + ex.gradeAmp * Math.sin((2 * Math.PI * now) / ex.gradePeriodSec + ex.gradePhase);
    15	  return Math.max(0.05, g);
    16	}
    17	
    18	/** Извлечение меди в концентрат (доля) при заданном содержании в питании. */
    19	export function recovery(cfg: SimConfig, gradePct: number): number {
    20	  const dev = Math.abs(gradePct - cfg.grade.targetPct);
    21	  return Math.max(0.5, cfg.grade.recoveryMax - cfg.grade.recoveryPenaltyPerPct * dev);
    22	}
    23	
    24	export function inBand(cfg: SimConfig, gradePct: number): boolean {
    25	  return Math.abs(gradePct - cfg.grade.targetPct) <= cfg.grade.bandPct;
    26	}
     1	/**
     2	 * Стратегии диспетчеризации самосвалов.
     3	 *
     4	 * 1. FixedStrategy — самосвал закреплён за одним экскаватором на всю смену (как на многих карьерах сейчас).
     5	 * 2. SmartStrategy — при каждом освобождении самосвал отправляется туда, где минимально ожидаемое
     6	 *    время до окончания погрузки (ETA проезда + прогноз очереди + время погрузки), с поправками
     7	 *    на отставание от плана по каждому материалу и на угрозу простоя дробилки.
     8	 */
     9	import type { Simulation } from './engine';
    10	import { gradeAt } from './ore';
    11	import { MATERIALS, type DumpSite, type Excavator, type Material, type StrategyName, type Truck } from './types';
    12	
    13	export interface DispatchStrategy {
    14	  readonly name: StrategyName;
    15	  /** Выбрать экскаватор для порожнего самосвала. */
    16	  choose(sim: Simulation, truck: Truck): number;
    17	  /** Реакция на поломку экскаватора. */
    18	  onExcavatorDown?(sim: Simulation, ex: Excavator): void;
    19	  /** Реакция на любое изменение обстановки (дороги, ремонт). */
    20	  onDisruption?(sim: Simulation): void;
    21	  /** Выбрать пункт разгрузки, когда их несколько (отвалы вскрыши). */
    22	  chooseDump?(sim: Simulation, truck: Truck, ex: Excavator, candidates: DumpSite[]): number;
    23	}
    24	
    25	export class FixedStrategy implements DispatchStrategy {
    26	  readonly name = 'fixed' as const;
    27	
    28	  choose(_sim: Simulation, truck: Truck): number {
    29	    return truck.fixedEx;
    30	  }
    31	}
    32	
    33	export interface Evaluation {
    34	  best: number;
    35	  /** Оценка (с) для каждого экскаватора: меньше — лучше. */
    36	  scores: number[];
    37	  /** Ожидаемое время до начала погрузки, с. */
    38	  waits: number[];
    39	  bonus: Record<Material, number>;
    40	}
    41	
    42	export class SmartStrategy implements DispatchStrategy {
    43	  readonly name = 'smart' as const;
    44	
    45	  /**
    46	   * Самосвал по умолчанию остаётся на своей «петле» (стартовое закрепление — как у плановика),
    47	   * но перезакрепляется, если другой экскаватор даёт выигрыш больше порога: очередь, поломка,
    48	   * отставание от плана, угроза простоя дробилки.
    49	   */
    50	  choose(sim: Simulation, truck: Truck): number {
    51	    const ev = this.evaluate(sim, truck);
    52	    const home = truck.homeEx;
    53	    if (ev.best !== home && !(ev.scores[home] - ev.scores[ev.best] <= sim.cfg.smart.stickinessSec)) truck.homeEx = ev.best;
    54	    return truck.homeEx;
    55	  }
    56	
    57	  evaluate(sim: Simulation, truck: Truck): Evaluation {
    58	    const { node, extra } = sim.routeOrigin(truck);
    59	    const dist = sim.router.from(node).dist;
    60	    const v = sim.speedEmpty;
    61	    const now = sim.now;
    62	
    63	    // Прогноз прибытия других самосвалов к каждому экскаватору: порожние — по оставшемуся пути,
    64	    // гружёные — вернутся на свою петлю после разгрузки.
    65	    const arrivals: number[][] = sim.excavators.map(() => []);
    66	    for (const o of sim.trucks) {
    67	      if (o === truck) continue;
    68	      if (o.dest?.kind === 'excavator') {
    69	        if (o.state === 'empty') arrivals[o.dest.id].push(now + sim.remainingDistance(o) / v);
    70	        else if (o.state === 'broken' && o.resumeState === 'empty')
    71	          arrivals[o.dest.id].push(now + o.timer + sim.remainingDistance(o) / v);
    72	      } else if (o.dest?.kind === 'dump' && o.loadT > 0) {
    73	        const dump = sim.dumps[o.dest.id];
    74	        const haul = o.state === 'loaded' || o.state === 'broken' ? sim.remainingDistance(o) / sim.speedLoaded : 0;
    75	        const repair = o.state === 'broken' ? o.timer : 0;
    76	        const back = sim.router.distance(dump.node, sim.excavators[o.homeEx].node) / v;
    77	        arrivals[o.homeEx].push(now + repair + haul + dump.dumpTimeSec + back);
    78	      }
    79	    }
    80	
    81	    const bonus = this.materialBonus(sim, truck);
    82	    const share = this.shareBonus(sim, truck);
    83	    const grade = this.gradeBonus(sim, truck);
    84	    const scores: number[] = [];
    85	    const waits: number[] = [];
    86	    let best = truck.fixedEx;
    87	    let bestScore = Infinity;
    88	    for (const ex of sim.excavators) {
    89	      const d = dist[ex.node] + extra;
    90	      if (!Number.isFinite(d)) {
    91	        scores.push(Infinity);
    92	        waits.push(Infinity);
    93	        continue;
    94	      }
    95	      const arrive = now + d / v;
    96	      const lt = sim.expectedLoadTime(ex);
    97	      const down = Math.max(ex.state === 'broken' ? ex.brokenLeft : ex.state === 'nostock' ? 4 * 3600 : 0, ex.blastLeft);
    98	      const free0 = now + down + (ex.loading !== null ? ex.loadLeft : 0) + ex.queue.length * lt;
    99	      // Прогоняем очередь с учётом уже едущих самосвалов: когда начнём грузиться мы
   100	      // и насколько наш приезд задержит тех, кто приедет позже (их ожидание — тоже потеря).
